function PasswordMeter({password}:{password:string}){const checks=[password.length>=8,/[A-Z]/.test(password),/[a-z]/.test(password),/[0-9]/.test(password),/[^A-Za-z0-9]/.test(password)];const score=checks.filter(Boolean).length;return <div className="password-meter"><div className="password-meter-track"><span style={{width:(score*20)+'%'}} className={'strength-'+score}/></div><small className="strength-label">{password.length===0?'Enter a password':score<=2?'Weak':score<=4?'Moderate':'Strong'}</small><div className="password-rules">{['At least 8 characters','One uppercase letter','One lowercase letter','One number','One special character'].map((rule,i)=><span key={rule} className={checks[i]?'rule-ok':'rule-pending'}>{checks[i]?'✓':'○'} {rule}</span>)}</div></div>}
