 const [accountMenu,setAccountMenu]=useState(false),[profileOpen,setProfileOpen]=useState(false),[profileBusy,setProfileBusy]=useState(false),[profileForm,setProfileForm]=useState({name:'',email:'',avatarUrl:''}),[passwordForm,setPasswordForm]=useState({currentPassword:'',newPassword:'',confirmPassword:''});
 const [showAuthPassword,setShowAuthPassword]=useState(false),[showCurrentPassword,setShowCurrentPassword]=useState(false),[showNewPassword,setShowNewPassword]=useState(false),[showConfirmPassword,setShowConfirmPassword]=useState(false),[showTeamPassword,setShowTeamPassword]=useState(false);
 const [form,setForm]=useState<Row>({}),[settings,setSettings]=useState<Row>({currency:'GHS',taxRate:0,taxInclusive:true,taxLabel:'VAT',setupCompleted:true}),[settingsOpen,setSettingsOpen]=useState(false);
