 async function savePassword(e:any){e.preventDefault();if(!isValidPassword(passwordForm.newPassword)){setNotice('Password must be at least 8 characters and include uppercase, lowercase, a number and a special character.');return}if(passwordForm.newPassword!==passwordForm.confirmPassword){setNotice('New passwords do not match');return}setProfileBusy(true);try{await sendPost('/api/auth/password',{currentPassword:passwordForm.currentPassword,newPassword:passwordForm.newPassword});setPasswordForm({currentPassword:'',newPassword:'',confirmPassword:''});setNotice('Password changed successfully. Other sessions were signed out.')}catch(e:any){setNotice(getApiErrorMessage(e, 'Password could not be changed'))}finally{setProfileBusy(false)}}
