 function rowValues(k:string,r:Row):any[]{switch(k){case'products':return[r.name,r.sku+(r.barcode?' / '+r.barcode:''),r.category,money(r.price),money(r.cost),r.stock,r.reorderLevel];case'sales':return[r.number||r.id?.slice(0,8),new Date(r.createdAt).toLocaleDateString(),r.customer,r.payment,r.refundedAt?<span title={r.refundReason}><s>{money(r.total)}</s> <span className="refund-tag">Refunded</span></span>:money(r.total),r.agentName||'—'];case'stock':return[new Date(r.createdAt).toLocaleDateString(),r.productName,r.type,r.qty,r.reason,r.actorName];case'suppliers':return[r.name,r.contact,r.phone,r.email,r.address];case'purchases':return[r.number,r.supplierName,r.productName,r.qty,money(r.total),r.status,r.expectedDate||'—'];case'expenses':return[r.date,r.description,r.category,r.payment,money(r.amount),r.actorName];case'invoices':return[r.number,new Date(r.createdAt).toLocaleDateString(),r.customer,r.description,money(r.total),r.status,r.dueDate||'—'];case'customers':return[r.name,r.phone||'—',r.visits,money(r.lifetimeValue||0)];case'team':return[r.name,r.email,r.role,r.active?'Active':'Disabled',new Date(r.createdAt).toLocaleDateString()];default:return Object.values(r).slice(0,6)}}
 if(!user)return <div className="auth"><section className="auth-left"><div className="logo"><Boxes/> ShopFlow</div><span>BUSINESS OPERATIONS PLATFORM</span><h1>One shop.<br/><i>Full control.</i></h1><p>Sales, inventory, procurement, finance and team permissions in one secure workspace.</p><div className="secure"><ShieldCheck/> Private sessions · CSRF protected</div></section><section className="auth-right"><form className="auth-form" onSubmit={authSubmit}><span className="eyebrow">YOUR BUSINESS, IN FOCUS</span><h2>{mode==='login'?'Welcome back':mode==='register'?'Create business workspace':mode==='forgot'?'Recover your password':'Set a new password'}</h2><p>{mode==='login'?'First registered account becomes Managing Director.':mode==='forgot'?'We will issue a time-limited recovery token if the account exists.':'Use the secure token from your recovery email.'}</p>{mode==='register'&&<label>Full name<input required value={auth.name} onChange={e=>setAuth({...auth,name:e.target.value})}/></label>}<label>Email address<input type="email" required value={auth.email} onChange={e=>setAuth({...auth,email:e.target.value})}/></label>{mode==='reset'&&<label>Recovery token<input required value={auth.token} onChange={e=>setAuth({...auth,token:e.target.value})}/></label>}{mode!=='forgot'&&<label>Password<div className="password-input"><input type={showAuthPassword?'text':'password'} required minLength={mode==='register'||mode==='reset'?8:1} value={auth.password} autoComplete={mode==='login'?'current-password':'new-password'} onChange={e=>setAuth({...auth,password:e.target.value})}/><button type="button" className="password-toggle" onClick={()=>setShowAuthPassword(!showAuthPassword)}>{showAuthPassword?'Hide':'Show'}</button></div></label>}{(mode==='register'||mode==='reset')&&<PasswordMeter password={auth.password}/>}<button className="primary wide">{mode==='login'?'Sign in':mode==='register'?'Create workspace':mode==='forgot'?'Send recovery instructions':'Reset password'}</button><p className="switch">{mode==='login'?<>New business? <button type="button" onClick={()=>setMode('register')}>Create account</button> · <button type="button" onClick={()=>setMode('forgot')}>Forgot password?</button></>:<button type="button" onClick={()=>setMode('login')}>Back to sign in</button>}</p>{notice&&<p className="notice">{notice}</p>}</form></section></div>;
 const needsSetup=user.role==='Managing Director'&&!settings.setupCompleted;
 if(needsSetup||settingsOpen)return <ShopSetup initial={settings} firstTime={needsSetup} userName={user.name} onCancel={needsSetup?undefined:()=>setSettingsOpen(false)} onSave={async(v:Row)=>{const r=await sendPost('/api/shop/settings',v);setSettings(r.data.settings);setSettingsOpen(false);setNotice(needsSetup?'Your shop is ready':'Shop settings saved')}}/>;
